import{_ as a,c as i,o,j as s,Y as r,t as n}from"./chunks/framework.BNTND4LZ.js";const m=JSON.parse('{"title":"git-update-ref | x-cmd man (git man1) | Update the object name stored in a ref safely","titleTemplate":false,"description":"x-cmd man (git man1 Manual Page) | git-update-ref - Update the object name stored in a ref safely","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"git-update-ref | x-cmd man (git man1) | Update the object name stored in a ref safely"}],["meta",{"name":"og:description","content":"x-cmd man (git man1 Manual Page) | git-update-ref - Update the object name stored in a ref safely"}]]},"headers":[],"params":{"isMan":true,"man":"git-update-ref","category":"git man1","desc":"Update the object name stored in a ref safely"},"relativePath":"git/man1/git-update-ref.md","filePath":"git/man1/[man].md"}'),l={name:"git/man1/git-update-ref.md"},p={class:"visually-hidden"};function h(t,e,d,u,g,c){return o(),i("div",null,[s("h1",p,n(t.$params.man),1),e[0]||(e[0]=r(`<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>git-update-ref - Update the object name stored in a ref safely</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update-ref</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [-m </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">reaso</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">n</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">]</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--no-deref] (</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">-d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">re</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">f</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [&lt;oldvalue&gt;] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--create-reflog] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ref</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt; </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">newvalu</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [&lt;oldvalue&gt;] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> --stdin</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [-z])</span></span></code></pre></div><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>Given two arguments, stores the &lt;newvalue&gt; in the &lt;ref&gt;, possibly dereferencing the symbolic refs. E.g. <strong>git update-ref HEAD &lt;newvalue&gt;</strong> updates the current branch head to the new object.</p><p>Given three arguments, stores the &lt;newvalue&gt; in the &lt;ref&gt;, possibly dereferencing the symbolic refs, after verifying that the current value of the &lt;ref&gt; matches &lt;oldvalue&gt;. E.g. <strong>git update-ref refs/heads/master &lt;newvalue&gt; &lt;oldvalue&gt;</strong> updates the master branch head to &lt;newvalue&gt; only if its current value is &lt;oldvalue&gt;. You can specify 40 &quot;0&quot; or an empty string as &lt;oldvalue&gt; to make sure that the ref you are creating does not exist.</p><p>It also allows a &quot;ref&quot; file to be a symbolic pointer to another ref file by starting with the four-byte header sequence of &quot;ref:&quot;.</p><p>More importantly, it allows the update of a ref file to follow these symbolic pointers, whether they are symlinks or these &quot;regular file symbolic refs&quot;. It follows <strong>real</strong> symlinks only if they start with &quot;refs/&quot;: otherwise it will just try to read them and update them as a regular file (i.e. it will allow the filesystem to follow them, but will overwrite such a symlink to somewhere else with a regular filename).</p><p>If --no-deref is given, &lt;ref&gt; itself is overwritten, rather than the result of following the symbolic pointers.</p><p>In general, using</p><blockquote><pre><code>git update-ref HEAD &quot;$head&quot;
</code></pre></blockquote><p>should be a <em>lot</em> safer than doing</p><blockquote><pre><code>echo &quot;$head&quot; &gt; &quot;$GIT_DIR/HEAD&quot;
</code></pre></blockquote><p>both from a symlink following standpoint <strong>and</strong> an error checking standpoint. The &quot;refs/&quot; rule for symlinks means that symlinks that point to &quot;outside&quot; the tree are safe: they&#39;ll be followed for reading but not for writing (so we&#39;ll never write through a ref symlink to some other tree, if you have copied a whole archive by creating a symlink tree).</p><p>With <strong>-d</strong> flag, it deletes the named &lt;ref&gt; after verifying it still contains &lt;oldvalue&gt;.</p><p>With <strong>--stdin</strong>, update-ref reads instructions from standard input and performs all modifications together. Specify commands of the form:</p><blockquote><pre><code>update SP &lt;ref&gt; SP &lt;newvalue&gt; [SP &lt;oldvalue&gt;] LF
create SP &lt;ref&gt; SP &lt;newvalue&gt; LF
delete SP &lt;ref&gt; [SP &lt;oldvalue&gt;] LF
verify SP &lt;ref&gt; [SP &lt;oldvalue&gt;] LF
option SP &lt;opt&gt; LF
start LF
prepare LF
commit LF
abort LF
</code></pre></blockquote><p>With <strong>--create-reflog</strong>, update-ref will create a reflog for each ref even if one would not ordinarily be created.</p><p>Quote fields containing whitespace as if they were strings in C source code; i.e., surrounded by double-quotes and with backslash escapes. Use 40 &quot;0&quot; characters or the empty string to specify a zero value. To specify a missing value, omit the value and its preceding SP entirely.</p><p>Alternatively, use <strong>-z</strong> to specify in NUL-terminated format, without quoting:</p><blockquote><pre><code>update SP &lt;ref&gt; NUL &lt;newvalue&gt; NUL [&lt;oldvalue&gt;] NUL
create SP &lt;ref&gt; NUL &lt;newvalue&gt; NUL
delete SP &lt;ref&gt; NUL [&lt;oldvalue&gt;] NUL
verify SP &lt;ref&gt; NUL [&lt;oldvalue&gt;] NUL
option SP &lt;opt&gt; NUL
start NUL
prepare NUL
commit NUL
abort NUL
</code></pre></blockquote><p>In this format, use 40 &quot;0&quot; to specify a zero value, and use the empty string to specify a missing value.</p><p>In either format, values can be specified in any form that Git recognizes as an object name. Commands in any other format or a repeated &lt;ref&gt; produce an error. Command meanings are:</p><p>update</p><blockquote><p>Set &lt;ref&gt; to &lt;newvalue&gt; after verifying &lt;oldvalue&gt;, if given. Specify a zero &lt;newvalue&gt; to ensure the ref does not exist after the update and/or a zero &lt;oldvalue&gt; to make sure the ref does not exist before the update.</p></blockquote><p>create</p><blockquote><p>Create &lt;ref&gt; with &lt;newvalue&gt; after verifying it does not exist. The given &lt;newvalue&gt; may not be zero.</p></blockquote><p>delete</p><blockquote><p>Delete &lt;ref&gt; after verifying it exists with &lt;oldvalue&gt;, if given. If given, &lt;oldvalue&gt; may not be zero.</p></blockquote><p>verify</p><blockquote><p>Verify &lt;ref&gt; against &lt;oldvalue&gt; but do not change it. If &lt;oldvalue&gt; is zero or missing, the ref must not exist.</p></blockquote><p>option</p><blockquote><p>Modify behavior of the next command naming a &lt;ref&gt;. The only valid option is <strong>no-deref</strong> to avoid dereferencing a symbolic ref.</p></blockquote><p>start</p><blockquote><p>Start a transaction. In contrast to a non-transactional session, a transaction will automatically abort if the session ends without an explicit commit. This command may create a new empty transaction when the current one has been committed or aborted already.</p></blockquote><p>prepare</p><blockquote><p>Prepare to commit the transaction. This will create lock files for all queued reference updates. If one reference could not be locked, the transaction will be aborted.</p></blockquote><p>commit</p><blockquote><p>Commit all reference updates queued for the transaction, ending the transaction.</p></blockquote><p>abort</p><blockquote><p>Abort the transaction, releasing all locks if the transaction is in prepared state.</p></blockquote><p>If all &lt;ref&gt;s can be locked with matching &lt;oldvalue&gt;s simultaneously, all modifications are performed. Otherwise, no modifications are performed. Note that while each individual &lt;ref&gt; is updated or deleted atomically, a concurrent reader may still see a subset of the modifications.</p><h2 id="logging-updates" tabindex="-1">LOGGING UPDATES <a class="header-anchor" href="#logging-updates" aria-label="Permalink to &quot;LOGGING UPDATES&quot;">​</a></h2><p>If config parameter &quot;core.logAllRefUpdates&quot; is true and the ref is one under &quot;refs/heads/&quot;, &quot;refs/remotes/&quot;, &quot;refs/notes/&quot;, or a pseudoref like HEAD or ORIG_HEAD; or the file &quot;$GIT_DIR/logs/&lt;ref&gt;&quot; exists then <strong>git update-ref</strong> will append a line to the log file &quot;$GIT_DIR/logs/&lt;ref&gt;&quot; (dereferencing all symbolic refs before creating the log name) describing the change in ref value. Log lines are formatted as:</p><blockquote><pre><code>oldsha1 SP newsha1 SP committer LF
</code></pre></blockquote><p>Where &quot;oldsha1&quot; is the 40 character hexadecimal value previously stored in &lt;ref&gt;, &quot;newsha1&quot; is the 40 character hexadecimal value of &lt;newvalue&gt; and &quot;committer&quot; is the committer&#39;s name, email address and date in the standard Git committer ident format.</p><p>Optionally with -m:</p><blockquote><pre><code>oldsha1 SP newsha1 SP committer TAB message LF
</code></pre></blockquote><p>Where all fields are as described above and &quot;message&quot; is the value supplied to the -m option.</p><p>An update will fail (without changing &lt;ref&gt;) if the current user is unable to create a new log file, append to the existing log file or does not have committer information available.</p><h2 id="git" tabindex="-1">GIT <a class="header-anchor" href="#git" aria-label="Permalink to &quot;GIT&quot;">​</a></h2><p>Part of the <strong>git</strong>(1) suite</p>`,53))])}const k=a(l,[["render",h]]);export{m as __pageData,k as default};
